<template><ion-page><ion-header><ion-toolbar><ion-buttons slot="start"><ion-menu-button /></ion-buttons><ion-title>BBOT Scans</ion-title><ion-buttons slot="end"><ion-button @click="load"><ion-icon :icon="refreshOutline" /></ion-button></ion-buttons></ion-toolbar></ion-header><ion-content class="ion-padding">
<ion-card><ion-card-header><ion-card-title>New BBOT scan</ion-card-title></ion-card-header><ion-card-content><ion-input v-model="target" label="Target" label-placement="stacked" fill="outline" placeholder="example.com"/><ion-select v-model="preset" label="Preset" label-placement="stacked" fill="outline" class="ion-margin-top"><ion-select-option v-for="item in presets" :key="item" :value="item">{{ item }}</ion-select-option></ion-select><ion-button expand="block" class="ion-margin-top" :disabled="!target.trim()||working" @click="start">Start scan</ion-button></ion-card-content></ion-card>
<ion-spinner v-if="loading"/><ion-card v-for="scan in scans" :key="scan.id"><ion-card-header><ion-card-subtitle>{{scan.preset}}</ion-card-subtitle><ion-card-title>{{scan.target}}</ion-card-title></ion-card-header><ion-card-content><ion-chip :color="color(scan.status)">{{scan.status}}</ion-chip><ion-chip>{{scan.event_count}} events</ion-chip><p v-if="scan.error" class="error">{{scan.error}}</p><ion-button fill="outline" size="small" @click="showEvents(scan)">View events</ion-button><ion-button v-if="active(scan.status)" fill="outline" color="warning" size="small" @click="stop(scan.id)">Stop</ion-button></ion-card-content></ion-card>
<ion-modal v-if="selected" :is-open="true" @did-dismiss="selected=null"><ion-header><ion-toolbar><ion-title>BBOT events</ion-title><ion-buttons slot="end"><ion-button @click="selected=null">Close</ion-button></ion-buttons></ion-toolbar></ion-header><ion-content class="ion-padding"><pre>{{JSON.stringify(events,null,2)}}</pre></ion-content></ion-modal>
</ion-content></ion-page></template>
<script setup lang="ts">import{onMounted,onUnmounted,ref}from'vue';import{refreshOutline}from'ionicons/icons';import{BBotService,type BBotScan}from'@/services/BBotService';const target=ref(''),preset=ref('subdomain-enum'),presets=ref<string[]>([]),scans=ref<BBotScan[]>([]),events=ref<unknown[]>([]),selected=ref<BBotScan|null>(null),loading=ref(false),working=ref(false);let timer:number|undefined;const active=(s:string)=>['QUEUED','STARTING','RUNNING','FINISHING'].includes(s);const color=(s:string)=>s==='FINISHED'?'success':s==='FAILED'?'danger':active(s)?'warning':'medium';const load=async()=>{loading.value=true;try{[presets.value,scans.value]=await Promise.all([BBotService.presets(),BBotService.scans()]);if(!presets.value.includes(preset.value))preset.value=presets.value[0]??''}finally{loading.value=false}};const start=async()=>{working.value=true;try{await BBotService.start(target.value,preset.value);target.value='';await load()}finally{working.value=false}};const stop=async(id:string)=>{await BBotService.stop(id);await load()};const showEvents=async(scan:BBotScan)=>{selected.value=scan;events.value=await BBotService.events(scan.id)};onMounted(()=>{load();timer=window.setInterval(()=>{if(scans.value.some(s=>active(s.status)))load()},5000)});onUnmounted(()=>{if(timer)clearInterval(timer)});</script>
<style scoped>ion-spinner{display:block;margin:32px auto}.error{color:var(--ion-color-danger)}pre{font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere}</style>
